using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("compiling=" + EditorApplication.isCompiling + " compilationFailed=" + EditorUtility.scriptCompilationFailed + " playing=" + EditorApplication.isPlaying + " telemetry=" + typeof(CampusDriveTelemetry).Assembly.GetName().Name);
        }
    }
}
